/**
 * Local Expo config plugin: pin the Android Gradle wrapper version.
 *
 * Why: the React Native 0.87 template generates `gradle/wrapper/gradle-wrapper.properties`
 * with Gradle 9.3.1, while the Android Gradle Plugin resolved for that same
 * template requires Gradle >= 9.4.1. A fresh `expo prebuild` therefore produces
 * a project that fails during configuration with:
 *
 *   Failed to apply plugin 'com.android.internal.version-check'.
 *   > Minimum supported Gradle version is 9.4.1. Current version is 9.3.1.
 *
 * `mobile/android/` is generated output (gitignored, regenerated by prebuild),
 * so the fix must be applied at generation time. This mod rewrites
 * `distributionUrl` after every prebuild — including `prebuild --clean`.
 *
 * Bump GRADLE_VERSION when the template's AGP minimum moves; prebuild will
 * enforce it automatically.
 */
const { withDangerousMod } = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

// Minimum Gradle version required by the template's Android Gradle Plugin.
const GRADLE_VERSION = '9.4.1';

function withGradleVersion(config) {
  return withDangerousMod(config, [
    'android',
    async (config) => {
      const projectRoot = config.modRequest.projectRoot;
      const wrapperFile = path.join(
        projectRoot,
        'android',
        'gradle',
        'wrapper',
        'gradle-wrapper.properties'
      );

      if (!fs.existsSync(wrapperFile)) {
        throw new Error(
          '[with-gradle-version] ' +
            wrapperFile +
            ' not found after prebuild. The android template layout may have ' +
            'changed upstream — check gradle/wrapper/ in the RN template.'
        );
      }

      let contents = fs.readFileSync(wrapperFile, 'utf8');
      const distributionUrl =
        'distributionUrl=https\\://services.gradle.org/distributions/' +
        'gradle-' +
        GRADLE_VERSION +
        '-bin.zip';

      if (/^distributionUrl=.*$/m.test(contents)) {
        contents = contents.replace(/^distributionUrl=.*$/m, distributionUrl);
      } else {
        contents = contents.trimEnd() + '\n' + distributionUrl + '\n';
      }

      fs.writeFileSync(wrapperFile, contents);
      return config;
    },
  ]);
}

module.exports = withGradleVersion;
